// Re-verify the 3 audit fixes end-to-end on live production
const OWNER_EMAIL = "iperez4242@gmail.com";
const BASE = "https://api.ivxholding.com";

async function rmint() {
  const rm = await fetch(BASE + "/api/ivx/owner-passwordless-login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email: OWNER_EMAIL }),
  });
  const rmj = await rm.json();
  if (rmj.accessToken) await Bun.file("/tmp/owner_at").write(rmj.accessToken);
  return rmj.accessToken || await Bun.file("/tmp/owner_at").text();
}
const token = await rmint();
async function getJSON(url) {
  const r = await fetch(url, { headers: { Authorization: "Bearer " + token } });
  const text = await r.text();
  let j = null; try { j = JSON.parse(text); } catch {}
  return { status: r.status, json: j, text };
}

// 1. Poll for deploy LIVE + 3-way SHA parity
console.log("=== Polling for deploy LIVE + 3-way SHA parity ===");
const gh = await fetch("https://api.github.com/repos/ibb142/rork-global-real-estate-invest/commits/main");
const ghj = await gh.json();
const githubSha = ghj.sha;
console.log("GitHub HEAD = " + githubSha);

const start = Date.now();
let parityAchieved = false;
let liveDeployId = null;
let lastDeployStatus = null;
while (Date.now() - start < 55000) {
  const rs = await getJSON(BASE + "/api/tool/render-status");
  const rd = rs.json?.data ?? {};
  const h = await fetch(BASE + "/health");
  const hj = await h.json();
  const ts = new Date().toISOString().slice(11, 19);
  if (rd.deployStatus !== lastDeployStatus) {
    console.log(`[${ts}] deploy=${rd.deployId} status=${rd.deployStatus} commit=${(rd.deployedCommitSha ?? "").slice(0,12)} | runtime=${(hj.commit ?? "").slice(0,12)} status=${hj.status}`);
    lastDeployStatus = rd.deployStatus;
  }
  if (rd.deployStatus === "live" && rd.deployedCommitSha === githubSha && hj.commit === githubSha) {
    parityAchieved = true;
    liveDeployId = rd.deployId;
    console.log("3-WAY SHA PARITY ACHIEVED");
    break;
  }
  if (rd.deployStatus === "update_failed" || rd.deployStatus === "canceled") {
    console.log("DEPLOY TERMINAL: " + rd.deployStatus);
    break;
  }
  await new Promise(r => setTimeout(r, 7000));
}

// 2. Verify the 3 fixes in the live executive layer
console.log("\n=== FIX 1: relabel '3 active investors' as deal-funding targets ===");
const el = await getJSON(BASE + "/api/ivx/executive-layer");
const elj = el.json?.executive || el.json;
const crm = elj?.dailyBriefing?.crmPipeline;
const inv = elj?.dailyBriefing?.investorPipeline;
console.log("CRM label: " + crm?.label);
console.log("CRM value: " + crm?.value);
console.log("CRM note: " + crm?.note);
console.log("Investor label: " + inv?.label);
console.log("Investor value: " + inv?.value);
console.log("Investor note: " + inv?.note);
const f1Pass = crm?.value?.includes("deal-funding target") && inv?.label?.includes("capital being sought");
console.log("FINDING 1 FIXED = " + f1Pass);

console.log("\n=== FIX 3: split autonomous runs by evidence ===");
const aa = elj?.autonomousActions;
console.log("totalRuns: " + aa?.totalRuns);
console.log("runsWithEvidence: " + aa?.runsWithEvidence);
console.log("runsWithoutEvidence: " + aa?.runsWithoutEvidence);
console.log("note: " + aa?.note);
const f3Pass = aa?.runsWithEvidence !== undefined && aa?.runsWithoutEvidence !== undefined && (aa?.runsWithEvidence + aa?.runsWithoutEvidence === aa?.totalRuns);
console.log("FINDING 3 FIXED = " + f3Pass);

console.log("\n=== FIX 2: AI=77 reproducible via /api/ivx/autonomous-core/dashboard ===");
const ac = await getJSON(BASE + "/api/ivx/autonomous-core/dashboard");
const acj = ac.json?.dashboard || ac.json;
const caps = acj?.capabilities || [];
const online = caps.filter(x => x.state === "online").length;
const partial = caps.filter(x => x.state === "partial").length;
const total = caps.length;
const aiScore = total > 0 ? Math.round(((online + partial * 0.5) / total) * 100) : 0;
console.log("capabilities: online=" + online + " partial=" + partial + " total=" + total);
console.log("REPRO AI score = " + aiScore + " (executive layer claims " + elj?.scorecards?.ai?.score + ")");
const f2Pass = aiScore === elj?.scorecards?.ai?.score && total > 0;
console.log("FINDING 2 FIXED (live-reproducible) = " + f2Pass);

// 3. Final evidence
const evidence = {
  githubSha,
  liveDeployId,
  parityAchieved,
  runtimeSha: (await fetch(BASE + "/health")).then(r => r.json()).then ? null : null,
  fix1RelabelDealFundingTargets: f1Pass,
  fix3SplitRunsByEvidence: f3Pass,
  fix2AIReproducible: f2Pass,
  executiveHeadline: elj?.headline,
  aiScorecard: elj?.scorecards?.ai,
  autonomousActions: { totalRuns: aa?.totalRuns, runsWithEvidence: aa?.runsWithEvidence, runsWithoutEvidence: aa?.runsWithoutEvidence },
  crmPipeline: crm,
  investorPipeline: inv,
};
console.log("\n=== FINAL EVIDENCE ===");
console.log(JSON.stringify(evidence, null, 2));

